from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
anchor='''                <div class="sidebar-item px-4 py-3 rounded-lg cursor-pointer flex items-center gap-3 text-gray-300 hover:bg-gray-800" onclick="navigate('youtube')">'''
nav='''                <div class="sidebar-item px-4 py-3 rounded-lg cursor-pointer flex items-center gap-3 text-gray-300 hover:bg-gray-800" onclick="navigate('skills')">
                    <i class="fa-solid fa-terminal w-5 text-center"></i><span>Skills & Research</span>
                    <span class="ml-auto text-[10px] font-bold px-1.5 py-0.5 rounded bg-emerald-600 text-white">11</span>
                </div>

                <div class="sidebar-item px-4 py-3 rounded-lg cursor-pointer flex items-center gap-3 text-gray-300 hover:bg-gray-800" onclick="navigate('vimax')">
                    <i class="fa-solid fa-film w-5 text-center"></i><span>ViMax Video Studio</span>
                    <span class="ml-auto text-[10px] font-bold px-1.5 py-0.5 rounded bg-purple-600 text-white">PRO</span>
                </div>

                <div class="sidebar-item px-4 py-3 rounded-lg cursor-pointer flex items-center gap-3 text-gray-300 hover:bg-gray-800" onclick="navigate('models')">
                    <i class="fa-solid fa-cubes w-5 text-center"></i><span>Models & Providers</span>
                    <span class="ml-auto text-[10px] font-bold px-1.5 py-0.5 rounded bg-blue-600 text-white">72</span>
                </div>

'''
assert anchor in s
s=s.replace(anchor,nav+anchor,1)
old="""                case 'agents': renderAgents(); break;
                case 'youtube': renderYouTube(); break;"""
new="""                case 'agents': renderAgents(); break;
                case 'skills': renderSkillsHub(); break;
                case 'vimax': renderViMaxStudio(); break;
                case 'models': renderModelsHub(); break;
                case 'youtube': renderYouTube(); break;"""
assert old in s
s=s.replace(old,new,1)
marker='''</script>'''
assert marker in s
js=r'''
    // ============================================================================
    // PHASE 3 — SKILLS, VIMAX, MODEL ROUTER
    // ============================================================================
    const esc3 = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const pretty3 = v => JSON.stringify(v, null, 2);
    async function aiRequest(path, method='GET', body=null) {
        const res = await fetch(`${API_BASE}${path}`, {
            method, headers: {'Content-Type':'application/json', ...(token ? {'Authorization':`Bearer ${token}`} : {})},
            body: body === null ? undefined : JSON.stringify(body)
        });
        let data={}; try { data=await res.json(); } catch (_) { data={detail:`HTTP ${res.status}`}; }
        if (res.status===401) { logout(); throw new Error('Unauthorized'); }
        if (!res.ok) { const d=data.detail; throw new Error(typeof d==='string'?d:(d?.error||pretty3(d||data))); }
        return data;
    }
    function busy3(id,on,label='Working…') { const b=document.getElementById(id); if(!b)return; b.disabled=on; b.dataset.old=b.dataset.old||b.innerHTML; b.innerHTML=on?`<i class="fa-solid fa-circle-notch fa-spin mr-2"></i>${label}`:b.dataset.old; }
    function resultBox3(data) { return `<pre class="mt-4 p-4 rounded-xl bg-black/30 border border-gray-700 text-xs text-emerald-200 overflow-auto max-h-[600px] whitespace-pre-wrap">${esc3(pretty3(data))}</pre>`; }

    async function renderSkillsHub() {
        const c=document.getElementById('contentArea');
        c.innerHTML=`<div class="max-w-6xl mx-auto space-y-6">
          <div class="glass-panel rounded-2xl p-6 border border-indigo-500/30">
            <div class="flex flex-wrap justify-between gap-4"><div><h2 class="text-2xl font-bold">YouTube Skills Console</h2><p class="text-gray-400 mt-1">11 installed skills · 21 hook formulas · exact slash commands</p></div><span class="px-3 py-1 h-fit rounded-full bg-emerald-500/15 text-emerald-300">/yt-script verified</span></div>
            <div class="mt-5 flex gap-2"><input id="skillCommand3" class="flex-1 bg-gray-900 border border-gray-700 rounded-xl px-4 py-3" value="/yt-script How small creators can win in 2026 --angle proof first --length medium"><button id="skillRun3" onclick="runSkill3()" class="px-5 py-3 rounded-xl bg-indigo-600 hover:bg-indigo-500 font-semibold">Run</button></div>
            <div class="flex flex-wrap gap-2 mt-3" id="skillChips3"></div><div id="skillResult3"></div>
          </div>
          <div class="grid lg:grid-cols-2 gap-6">
            <div class="glass-panel rounded-2xl p-6"><h3 class="font-bold text-lg"><i class="fa-solid fa-globe mr-2 text-blue-400"></i>Browser Research Skill</h3><p class="text-sm text-gray-400 mt-1">Search → read public pages → extract sourced facts. Private/internal URLs are blocked.</p><input id="researchTopic3" class="w-full mt-4 bg-gray-900 border border-gray-700 rounded-xl px-4 py-3" placeholder="Topic to research"><input id="researchAngle3" class="w-full mt-2 bg-gray-900 border border-gray-700 rounded-xl px-4 py-3" placeholder="Angle (optional)"><button id="researchRun3" onclick="runResearch3()" class="mt-3 w-full py-3 rounded-xl bg-blue-600 hover:bg-blue-500 font-semibold">Research with sources</button><div id="researchResult3"></div></div>
            <div class="glass-panel rounded-2xl p-6"><h3 class="font-bold text-lg">Installed toolchain</h3><div class="mt-4 grid grid-cols-2 gap-2 text-sm text-gray-300">${['Hook scoring','Titles + thumbnails','Chapters','Dead-air EDL','Retention CSV','Viral swipe','SEO','Shorts','Comments','Channel audit','Content plan','Browser research'].map(x=>`<div class="p-2 rounded-lg bg-gray-800/70"><i class="fa-solid fa-check text-emerald-400 mr-2"></i>${x}</div>`).join('')}</div><p class="text-xs text-gray-500 mt-4">Sources: youtube-agent-skill, youtube-skills, BrowserSkill. Heavy browser automation uses an external browser worker; this Vercel-safe layer performs SSRF-protected HTTP research.</p></div>
          </div></div>`;
        try { const d=await aiRequest('/api/skills'); const names=(d.skills||[]).map(x=>x.name||x.command).filter(Boolean); const fallback=['yt-script','yt-package','yt-audit','yt-plan','yt-seo','yt-shorts','yt-comment']; document.getElementById('skillChips3').innerHTML=(names.length?names:fallback).map(n=>`<button onclick="document.getElementById('skillCommand3').value='/${esc3(n)} '" class="text-xs px-3 py-1.5 rounded-full bg-gray-800 hover:bg-gray-700">/${esc3(n)}</button>`).join(''); } catch(e){ toast(e.message,'error'); }
    }
    async function runSkill3(){ const out=document.getElementById('skillResult3'); busy3('skillRun3',true,'Running skill…'); out.innerHTML=''; try{const d=await aiRequest('/api/skills/command','POST',{command:document.getElementById('skillCommand3').value}); out.innerHTML=resultBox3(d);}catch(e){out.innerHTML=`<p class="mt-3 text-red-400">${esc3(e.message)}</p>`;}finally{busy3('skillRun3',false);} }
    async function runResearch3(){ const out=document.getElementById('researchResult3'); busy3('researchRun3',true,'Reading sources…'); out.innerHTML=''; try{const d=await aiRequest('/api/browse/research','POST',{topic:document.getElementById('researchTopic3').value,angle:document.getElementById('researchAngle3').value,max_pages:4}); out.innerHTML=`<div class="mt-4 text-sm text-emerald-300">Read ${d.pages_read} pages · ${d.facts.length} sourced facts</div>`+resultBox3(d);}catch(e){out.innerHTML=`<p class="mt-3 text-red-400">${esc3(e.message)}</p>`;}finally{busy3('researchRun3',false);} }

    let vimaxHome3=null, vimaxProject3=null;
    async function renderViMaxStudio(){ const c=document.getElementById('contentArea'); c.innerHTML=`<div class="max-w-7xl mx-auto space-y-6"><div class="glass-panel rounded-2xl p-6 border border-purple-500/30"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="text-2xl font-bold">ViMax Agentic Video Studio</h2><p class="text-gray-400">Idea → planner → characters → scenes → script → storyboard → keyframes → Veo/Wan clips → timeline</p></div><a href="https://github.com/HKUDS/ViMax" target="_blank" class="text-purple-300 text-sm">MIT source <i class="fa-solid fa-arrow-up-right-from-square"></i></a></div></div><div id="vimaxApp3" class="glass-panel rounded-2xl p-6"><div class="loader mx-auto"></div></div></div>`; try{vimaxHome3=await aiRequest('/api/vimax'); drawViMaxForm3();}catch(e){document.getElementById('vimaxApp3').innerHTML=`<p class="text-red-400">${esc3(e.message)}</p>`;} }
    function opts3(cap){ return (vimaxHome3?.models?.[cap]||[]).map(m=>`<option value="${esc3(m.id)}" ${!m.configured?'disabled':''}>${m.configured?'●':'○'} ${esc3(m.label)}${m.free?' · FREE':''}</option>`).join(''); }
    function drawViMaxForm3(){ document.getElementById('vimaxApp3').innerHTML=`<div class="grid lg:grid-cols-3 gap-5"><div class="lg:col-span-2"><label class="text-sm text-gray-400">Pipeline</label><select id="vxPipeline3" class="w-full mt-1 bg-gray-900 border border-gray-700 rounded-xl p-3"><option value="idea2video">Idea → Video</option><option value="script2video">Script → Video</option><option value="novel2movie">Novel/Article → Movie</option></select><label class="block text-sm text-gray-400 mt-4">Idea, script or long text</label><textarea id="vxIdea3" rows="8" class="w-full mt-1 bg-gray-900 border border-gray-700 rounded-xl p-3" placeholder="A 60-second documentary about the last bookbinder in Lahore…"></textarea><div class="grid sm:grid-cols-3 gap-3 mt-3"><div><label class="text-xs text-gray-400">Duration</label><input id="vxDuration3" type="number" value="60" class="w-full bg-gray-900 border border-gray-700 rounded-lg p-2"></div><div><label class="text-xs text-gray-400">Shots</label><input id="vxShots3" type="number" value="8" class="w-full bg-gray-900 border border-gray-700 rounded-lg p-2"></div><div><label class="text-xs text-gray-400">Aspect</label><select id="vxAspect3" class="w-full bg-gray-900 border border-gray-700 rounded-lg p-2"><option>16:9</option><option>9:16</option><option>1:1</option></select></div></div></div><div class="space-y-3"><div><label class="text-xs text-gray-400">Strong AI brain</label><select id="vxChat3" class="w-full bg-gray-900 border border-gray-700 rounded-lg p-2">${opts3('chat')}</select></div><div><label class="text-xs text-gray-400">Keyframe model</label><select id="vxImage3" class="w-full bg-gray-900 border border-gray-700 rounded-lg p-2">${opts3('image')}</select></div><div><label class="text-xs text-gray-400">Video model</label><select id="vxVideo3" class="w-full bg-gray-900 border border-gray-700 rounded-lg p-2">${opts3('video')}</select></div><div><label class="text-xs text-gray-400">Voice</label><select id="vxTts3" class="w-full bg-gray-900 border border-gray-700 rounded-lg p-2">${opts3('tts')}</select></div><label class="flex gap-2 items-center text-sm"><input id="vxImages3" type="checkbox"> Generate keyframes now</label><label class="flex gap-2 items-center text-sm"><input id="vxVoice3" type="checkbox"> Generate voiceover now</label><label class="flex gap-2 items-center text-sm"><input id="vxVideoNow3" type="checkbox"> Queue video clips now</label><p class="text-xs text-amber-300">Planning is free. GPU boxes only run when checked.</p></div></div><button id="vxRun3" onclick="runViMax3()" class="w-full mt-5 py-3 rounded-xl bg-gradient-to-r from-purple-600 to-indigo-600 font-bold">Build project</button><div id="vxResult3"></div>`; }
    async function runViMax3(){busy3('vxRun3',true,'Agents are planning…');const out=document.getElementById('vxResult3');out.innerHTML='';try{const pipeline=document.getElementById('vxPipeline3').value;const text=document.getElementById('vxIdea3').value;const body={duration_seconds:+document.getElementById('vxDuration3').value,shots:+document.getElementById('vxShots3').value,aspect_ratio:document.getElementById('vxAspect3').value,chat_model:document.getElementById('vxChat3').value,image_model:document.getElementById('vxImage3').value,video_model:document.getElementById('vxVideo3').value,tts_model:document.getElementById('vxTts3').value,generate_images:document.getElementById('vxImages3').checked,generate_voiceover:document.getElementById('vxVoice3').checked,render_video:document.getElementById('vxVideoNow3').checked,max_images:+document.getElementById('vxShots3').value,max_clips:document.getElementById('vxVideoNow3').checked?4:0};body[pipeline==='idea2video'?'idea':pipeline==='script2video'?'script':'novel']=text;vimaxProject3=await aiRequest(`/api/vimax/${pipeline}/run`,'POST',body);drawViMaxResult3(vimaxProject3);toast('ViMax project saved','success');}catch(e){out.innerHTML=`<p class="mt-4 text-red-400">${esc3(e.message)}</p>`;}finally{busy3('vxRun3',false);} }
    function drawViMaxResult3(d){const out=document.getElementById('vxResult3');const shots=d.shots||[];out.innerHTML=`<div class="mt-6 border-t border-gray-700 pt-5"><div class="flex flex-wrap justify-between gap-2"><div><h3 class="text-xl font-bold">${esc3(d.plan?.title||d.title||'ViMax Project')}</h3><p class="text-sm text-gray-400">Project #${d.project_id} · ${shots.length} shots · ${esc3(d.timeline?.meta?.duration_tc||'')}</p></div><button onclick="downloadViMax3()" class="px-3 py-2 rounded-lg bg-gray-800">Download timeline JSON</button></div><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-3 mt-4">${shots.map(s=>`<div class="rounded-xl bg-gray-900 border border-gray-700 p-3"><div class="text-xs text-purple-300">SHOT ${s.index} · ${esc3(s.shot_size)} · ${s.duration_seconds}s</div><p class="font-medium mt-2">${esc3(s.action)}</p><p class="text-xs text-gray-400 mt-2">${esc3(s.camera)} / ${esc3(s.movement)}</p><p class="text-xs text-gray-500 mt-2 line-clamp-3">${esc3(s.full_prompt)}</p><div class="mt-2 text-xs ${s.keyframe?'text-emerald-300':'text-gray-500'}">${s.keyframe?'✓ keyframe':'○ prompt ready'} · ${s.clip_job?'video queued':'clip not queued'}</div></div>`).join('')}</div><details class="mt-4"><summary class="cursor-pointer text-indigo-300">Full pipeline result</summary>${resultBox3(d)}</details></div>`; }
    function downloadViMax3(){if(!vimaxProject3)return;const b=new Blob([pretty3(vimaxProject3.timeline)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='bglabs-vimax-timeline.json';a.click();URL.revokeObjectURL(a.href);}

    let modelData3=null, modelCap3='all';
    async function renderModelsHub(){const c=document.getElementById('contentArea');c.innerHTML=`<div class="max-w-7xl mx-auto space-y-6"><div class="glass-panel rounded-2xl p-6 border border-blue-500/30"><div class="flex flex-wrap justify-between gap-4"><div><h2 class="text-2xl font-bold">Models & Provider Hub</h2><p class="text-gray-400">One backend for hosted APIs, HF Spaces and your own GPU repos</p></div><button onclick="showKeys3()" class="px-4 py-2 rounded-xl bg-blue-600 font-semibold"><i class="fa-solid fa-key mr-2"></i>AI Keys / Server URLs</button></div><div id="modelStats3" class="mt-4"></div></div><div id="keysPanel3"></div><div class="glass-panel rounded-2xl p-5"><div id="modelFilters3" class="flex flex-wrap gap-2"></div><div id="modelsGrid3" class="grid md:grid-cols-2 xl:grid-cols-3 gap-3 mt-5"><div class="loader"></div></div></div><div id="modelTry3"></div></div>`;try{modelData3=await aiRequest('/api/models');drawModels3();}catch(e){document.getElementById('modelsGrid3').innerHTML=`<p class="text-red-400">${esc3(e.message)}</p>`;} }
    function drawModels3(){const caps=modelData3.capabilities||[];const ready=modelData3.models.filter(m=>m.configured).length;document.getElementById('modelStats3').innerHTML=`<div class="flex flex-wrap gap-4 text-sm"><span class="text-emerald-300">● ${ready} ready now</span><span>${modelData3.models.length} model routes</span><span>${modelData3.status.repos.length} source repos</span><span class="text-amber-300">Free defaults: Pollinations · edge-tts · F5 Space · timeline</span></div>`;document.getElementById('modelFilters3').innerHTML=['all',...caps].map(x=>`<button onclick="filterModels3('${x}')" class="px-3 py-1.5 rounded-full text-sm ${modelCap3===x?'bg-indigo-600':'bg-gray-800'}">${x}</button>`).join('');const list=modelCap3==='all'?modelData3.models:modelData3.models.filter(m=>m.capability===modelCap3);document.getElementById('modelsGrid3').innerHTML=list.map(m=>`<div class="rounded-xl border ${m.configured?'border-emerald-500/30':'border-gray-700'} bg-gray-900/70 p-4"><div class="flex justify-between gap-2"><div><div class="font-semibold">${esc3(m.label)}</div><div class="text-xs text-gray-500 mt-1">${esc3(m.capability)} · ${esc3(m.backend)} · quality ${'★'.repeat(m.quality)}</div></div><span class="text-xs h-fit px-2 py-1 rounded-full ${m.configured?'bg-emerald-500/15 text-emerald-300':'bg-gray-800 text-gray-500'}">${m.configured?'READY':esc3(m.needs||'OFF')}</span></div><p class="text-xs text-gray-400 mt-3 min-h-[48px]">${esc3(m.notes)}</p><div class="mt-3 flex gap-2"><button ${m.configured?'': 'disabled'} onclick="tryModel3('${m.id}','${m.capability}')" class="flex-1 py-2 rounded-lg ${m.configured?'bg-indigo-600 hover:bg-indigo-500':'bg-gray-800 text-gray-600'} text-sm">Try</button><a href="${esc3(m.repo)}" target="_blank" class="px-3 py-2 rounded-lg bg-gray-800 text-sm">Repo</a></div></div>`).join('')||'<p>No models in this category.</p>';}
    function filterModels3(c){modelCap3=c;drawModels3();}
    async function showKeys3(){const p=document.getElementById('keysPanel3');p.innerHTML=`<div class="glass-panel rounded-2xl p-5"><div class="flex justify-between"><div><h3 class="font-bold text-lg">Bring Your Own Keys / GPU Servers</h3><p class="text-xs text-gray-400">Values are masked after save. Paste ComfyUI/LiveTalking URLs here too.</p></div><button onclick="document.getElementById('keysPanel3').innerHTML=''">✕</button></div><div id="keysGrid3" class="grid md:grid-cols-2 xl:grid-cols-3 gap-2 mt-4"><div class="loader"></div></div></div>`;try{const d=await aiRequest('/api/providers/keys');document.getElementById('keysGrid3').innerHTML=d.keys.map(k=>`<div class="p-3 rounded-lg bg-gray-900 border border-gray-700"><div class="flex justify-between"><div class="text-sm font-medium">${esc3(k.label)}</div><span class="text-xs ${k.active?'text-emerald-300':'text-gray-600'}">${k.active?'● '+esc3(k.source):'○ off'}</span></div><div class="text-[11px] text-gray-500 mt-1">${esc3(k.name)} · ${esc3(k.unlocks)}</div><div class="flex gap-1 mt-2"><input id="key_${k.name}" type="password" class="min-w-0 flex-1 bg-black/30 border border-gray-700 rounded px-2 py-1 text-xs" placeholder="${esc3(k.masked||'paste value')}"><button onclick="saveKey3('${k.name}')" class="px-2 rounded bg-blue-600 text-xs">Save</button>${k.stored_by_you?`<button onclick="delKey3('${k.name}')" class="px-2 rounded bg-red-900 text-xs">×</button>`:''}</div></div>`).join('');}catch(e){document.getElementById('keysGrid3').innerHTML=`<p class="text-red-400">${esc3(e.message)}</p>`;} }
    async function saveKey3(name){const el=document.getElementById('key_'+name);if(!el.value)return toast('Paste a value first','error');try{await aiRequest('/api/providers/keys/'+encodeURIComponent(name),'PUT',{value:el.value});toast(name+' saved','success');await showKeys3();modelData3=await aiRequest('/api/models');drawModels3();}catch(e){toast(e.message,'error');}}
    async function delKey3(name){try{await aiRequest('/api/providers/keys/'+encodeURIComponent(name),'DELETE');toast(name+' deleted','success');await showKeys3();modelData3=await aiRequest('/api/models');drawModels3();}catch(e){toast(e.message,'error');}}
    function tryModel3(id,cap){document.getElementById('modelTry3').innerHTML=`<div class="glass-panel rounded-2xl p-5"><h3 class="font-bold">Try ${esc3(id)} · ${esc3(cap)}</h3><textarea id="tryPrompt3" rows="4" class="w-full mt-3 bg-gray-900 border border-gray-700 rounded-xl p-3" placeholder="${cap==='tts'?'Text to speak':cap==='avatar'?'Prompt (also provide image/audio URLs below)':'Describe what you need'}"></textarea><div class="grid md:grid-cols-2 gap-2 mt-2"><input id="tryImage3" class="bg-gray-900 border border-gray-700 rounded-lg p-2 text-sm" placeholder="Image URL (image-to-video/avatar/edit)"><input id="tryAudio3" class="bg-gray-900 border border-gray-700 rounded-lg p-2 text-sm" placeholder="Audio URL (avatar/transcribe)"></div><button id="tryRun3" onclick="runModel3('${id}','${cap}')" class="mt-3 px-5 py-2 rounded-lg bg-indigo-600">Generate</button><div id="tryOut3"></div></div>`;document.getElementById('modelTry3').scrollIntoView({behavior:'smooth'});}
    async function runModel3(id,cap){busy3('tryRun3',true,'Generating…');const out=document.getElementById('tryOut3');out.innerHTML='';const text=document.getElementById('tryPrompt3').value;try{const d=await aiRequest('/api/generate/'+cap,'POST',{model:id,text,prompt:text,image_url:document.getElementById('tryImage3').value,audio_url:document.getElementById('tryAudio3').value,aspect_ratio:'16:9'});let media='';const u=mediaUrl(d.url,d.data_uri);if(u&&cap==='image')media=`<img src="${esc3(u)}" class="mt-4 max-h-96 rounded-xl">`;if(u&&cap==='tts')media=`<audio controls src="${esc3(u)}" class="mt-4 w-full"></audio>`;if(u&&(cap==='video'||cap==='avatar'))media=`<video controls src="${esc3(u)}" class="mt-4 max-h-96 rounded-xl"></video>`;out.innerHTML=media+resultBox3(d);}catch(e){out.innerHTML=`<p class="mt-3 text-red-400">${esc3(e.message)}</p>`;}finally{busy3('tryRun3',false);} }
'''
s=s.replace(marker,js+'\n    '+marker,1)
p.write_text(s,encoding='utf-8')
print('patched',len(s),'bytes')
